import{_ as a}from"./chunks/kuka_control_center.CLR_jZ0I.js";import{_ as o}from"./chunks/krc_backup_diff.FXLcgDew.js";import{_ as r}from"./chunks/control_flow_graph.hbF2msHR.js";import{_ as t}from"./chunks/cell_flowchart.DffnEFAW.js";import{_ as i,o as l,c,a0 as n}from"./chunks/framework.QP0FkqbW.js";const K=JSON.parse('{"title":"👑 Pro & Industrial Edition — Премиум функции KUKA KRL Professional","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guide/pro-features.md","filePath":"ru/guide/pro-features.md"}'),d={name:"ru/guide/pro-features.md"};function p(s,e,h,u,k,m){return l(),c("div",null,[...e[0]||(e[0]=[n('<h1 id="👑-pro-industrial-edition-—-премиум-функции-kuka-krl-professional" tabindex="-1">👑 Pro &amp; Industrial Edition — Премиум функции KUKA KRL Professional <a class="header-anchor" href="#👑-pro-industrial-edition-—-премиум-функции-kuka-krl-professional" aria-label="Permalink to &quot;👑 Pro &amp; Industrial Edition — Премиум функции KUKA KRL Professional&quot;">​</a></h1><p>Инструменты статического анализа, визуализации алгоритмов и промышленной безопасности для системных интеграторов.</p><hr><h3 id="_16-панель-управления-kuka-control-center-v1-8-5-pro-hub" tabindex="-1">16. Панель управления KUKA Control Center (v1.8.5 Pro Hub) <a class="header-anchor" href="#_16-панель-управления-kuka-control-center-v1-8-5-pro-hub" aria-label="Permalink to &quot;16. Панель управления KUKA Control Center (v1.8.5 Pro Hub)&quot;">​</a></h3><p>Нативный Fluent UI дашборд (<code>krl.openControlCenter</code>) для быстрого вызова всех Pro-инструментов, статического анализа проекта и связи со службой поддержки.</p><p><img src="'+a+'" alt="KUKA Control Center Demo"></p><hr><h3 id="_17-интерактивная-обратная-связь-и-чат-в-vs-code-telegram-support-panel" tabindex="-1">17. Интерактивная обратная связь и чат в VS Code (Telegram Support Panel) <a class="header-anchor" href="#_17-интерактивная-обратная-связь-и-чат-в-vs-code-telegram-support-panel" aria-label="Permalink to &quot;17. Интерактивная обратная связь и чат в VS Code (Telegram Support Panel)&quot;">​</a></h3><p>Встроенная панель чата поддержки (<code>krl.openTelegramChat</code>) с интеграцией Telegram-бота <strong><code>@kukakrlbot</code></strong>.</p><hr><h3 id="_18-автономная-консоль-администратора-kukaadminhelpdesk-exe" tabindex="-1">18. Автономная Консоль Администратора (<code>KukaAdminHelpdesk.exe</code>) <a class="header-anchor" href="#_18-автономная-консоль-администратора-kukaadminhelpdesk-exe" aria-label="Permalink to &quot;18. Автономная Консоль Администратора (`KukaAdminHelpdesk.exe`)&quot;">​</a></h3><p>Нативное Windows приложение для централизованного мониторинга статусов инженерных станций в цеху.</p><hr><h3 id="_19-krc-backup-diff-point-delta-inspector" tabindex="-1">19. KRC Backup Diff &amp; Point Delta Inspector <a class="header-anchor" href="#_19-krc-backup-diff-point-delta-inspector" aria-label="Permalink to &quot;19. KRC Backup Diff &amp; Point Delta Inspector&quot;">​</a></h3><p>Автоматическое сравнение ZIP-бэкапов KRC4/KRC5 с расчётом дельт координат ($\\Delta X, \\Delta Y, \\Delta Z, \\Delta A, \\Delta B, \\Delta C$) точек <code>E6POS</code>.</p><p><img src="'+o+'" alt="KRC Backup Diff Demo"></p><hr><h3 id="_20-интерактивныи-генератор-траектории-и-сниппетов-движения" tabindex="-1">20. Интерактивный генератор траекторий и сниппетов движения <a class="header-anchor" href="#_20-интерактивныи-генератор-траектории-и-сниппетов-движения" aria-label="Permalink to &quot;20. Интерактивный генератор траекторий и сниппетов движения&quot;">​</a></h3><p>Генератор движений KUKA (<code>PTP</code>, <code>LIN</code>, <code>CIRC</code>, <code>SPTP</code>, <code>SLIN</code>, <code>SCIRC</code>, <code>SPLINE Block</code>) с динамической векторной SVG-схемой траектории TCP и профилем рывка <code>$SGEAR_JERK</code>.</p><hr><h3 id="_21-интерактивныи-просмотрщик-блок-схем-control-flow-graph-flowchart" tabindex="-1">21. Интерактивный просмотрщик блок-схем (Control Flow Graph / Flowchart) <a class="header-anchor" href="#_21-интерактивныи-просмотрщик-блок-схем-control-flow-graph-flowchart" aria-label="Permalink to &quot;21. Интерактивный просмотрщик блок-схем (Control Flow Graph / Flowchart)&quot;">​</a></h3><p>Превращает логику <code>.src</code> в наглядные блок-схемы Mermaid SVG с возможностью проваливания в подпрограммы (drill-down).</p><p><img src="'+r+'" alt="Control Flow Graph Demo"><img src="'+t+'" alt="Cell Flowchart SVG"></p><hr><h3 id="_22-ethernetkrl-eki-suite-handler-generator" tabindex="-1">22. EthernetKRL (EKI) Suite &amp; Handler Generator <a class="header-anchor" href="#_22-ethernetkrl-eki-suite-handler-generator" aria-label="Permalink to &quot;22. EthernetKRL (EKI) Suite &amp; Handler Generator&quot;">​</a></h3><p>Валидатор XML-схем и автоматический генератор KRL-модулей сетевого обмена по TCP/IP.</p><hr><h3 id="_23-диагностика-промышленнои-безопасности-safety-velocity-check" tabindex="-1">23. Диагностика промышленной безопасности (Safety &amp; Velocity Check) <a class="header-anchor" href="#_23-диагностика-промышленнои-безопасности-safety-velocity-check" aria-label="Permalink to &quot;23. Диагностика промышленной безопасности (Safety &amp; Velocity Check)&quot;">​</a></h3><p>Проверка превышения скоростей <code>$VEL.CP &gt; 3.0 m/s</code>, неинициализированных <code>$TOOL</code>/<code>$BASE</code> и опасной кириллицы в исполняемых строках.</p><hr><h3 id="_24-ai-supportive-domain-context-tools-kuka-get-io-matrix-kuka-check-safety" tabindex="-1">24. AI-Supportive Domain Context Tools (<code>@kuka /get-io-matrix</code>, <code>@kuka /check-safety</code>) <a class="header-anchor" href="#_24-ai-supportive-domain-context-tools-kuka-get-io-matrix-kuka-check-safety" aria-label="Permalink to &quot;24. AI-Supportive Domain Context Tools (`@kuka /get-io-matrix`, `@kuka /check-safety`)&quot;">​</a></h3><p>Провайдеры контекста и AST для встроенного ИИ (Google Antigravity IDE / Copilot).</p><hr><h3 id="_25-3-point-frame-calculator-калькулятор-баз-и-инструментов" tabindex="-1">25. 3-Point Frame Calculator (Калькулятор баз и инструментов) <a class="header-anchor" href="#_25-3-point-frame-calculator-калькулятор-баз-и-инструментов" aria-label="Permalink to &quot;25. 3-Point Frame Calculator (Калькулятор баз и инструментов)&quot;">​</a></h3><p>Расчёт матрицы трансформации и углов фреймов <code>BASE_DATA[x]</code> по 3 точкам (Origin, X, XY).</p><hr><h3 id="_26-генератор-отчетов-приемки-quality-acceptance-report" tabindex="-1">26. Генератор отчётов приёмки (Quality Acceptance Report) <a class="header-anchor" href="#_26-генератор-отчетов-приемки-quality-acceptance-report" aria-label="Permalink to &quot;26. Генератор отчётов приёмки (Quality Acceptance Report)&quot;">​</a></h3><p>Выгрузка технического отчёта о качестве кода для сдачи проекта заказчику.</p>',38)])])}const g=i(d,[["render",p]]);export{K as __pageData,g as default};
